//lxrtxdy!
#pragma GCC optimize("O3")
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
constexpr int MAX_N = 7100;
constexpr ll INF = 1000000000;

struct Maxflow {
    struct Edge {
        int from, to;
        ll flow, capacity;
    };

    int s, t;
    vector<Edge> edges;
    vector<int> adj[MAX_N];
    int dist[MAX_N], visited[MAX_N], cur[MAX_N];

    void clear() {
        edges.clear();
        for (int i = 0; i < MAX_N; ++i) adj[i].clear();
    }

    void add_edge(int u, int v, ll cap) {
        edges.push_back({u, v, 0, cap});
        edges.push_back({v, u, 0, 0});
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool bfs() {
        memset(visited, 0, sizeof(visited));
        memset(dist, 0, sizeof(dist));
        queue<int> q;
        q.push(s);
        visited[s] = true;
        dist[s] = 0;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int idx : adj[u]) {
                auto &e = edges[idx];
                int v = e.to;
                if (!visited[v] && e.capacity > e.flow) {
                    dist[v] = dist[u] + 1;
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
        return visited[t];
    }

    ll dfs(int u, ll flow) {
        if (u == t || !flow) return flow;
        ll pushed = 0;
        for (int &i = cur[u]; i < (int)adj[u].size(); ++i) {
            int idx = adj[u][i];
            auto &e = edges[idx];
            if (dist[e.to] == dist[u] + 1) {
                ll f = dfs(e.to, min(flow, e.capacity - e.flow));
                if (f > 0) {
                    e.flow += f;
                    edges[idx ^ 1].flow -= f;
                    pushed += f;
                    flow -= f;
                    if (!flow) break;
                }
            }
        }
        return pushed;
    }

    ll max_flow() {
        ll result = 0;
        while (bfs()) {
            memset(cur, 0, sizeof(cur));
            result += dfs(s, INF);
        }
        return result;
    }
};

Maxflow mf;
char grid1[14][14], grid2[14][14];
bool vis[14][14];
int dist_grid[14][14];
int n, t;
int target_idx[103];

void bfs_dist(int sx, int sy) {
    queue<tuple<int, int, int>> q;
    for (int i = 0; i < 14; ++i)
        fill(dist_grid[i], dist_grid[i] + 14, 111);

    dist_grid[sx][sy] = 0;
    q.emplace(sx, sy, 0);

    const int dx[4] = {1, 0, 0, -1};
    const int dy[4] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [x, y, d] = q.front(); q.pop();
        if (vis[x][y]) continue;
        vis[x][y] = true;
        dist_grid[x][y] = d;

        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !vis[nx][ny] && grid1[nx][ny] != 'Y') {
                q.emplace(nx, ny, d + 1);
            }
        }
    }
}

int idx(int level, int x, int y) {
    return level * n * n + (x - 1) * n + y;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> t;
    for (int i = 1; i <= n; ++i) cin >> (grid1[i] + 1);
    for (int i = 1; i <= n; ++i) cin >> (grid2[i] + 1);

    mf.clear();
    mf.s = 0;
    mf.t = MAX_N - 2;

    int sx = 0, sy = 0;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') {
                sx = i; sy = j;
                break;
            }
        }
    }

    for (int i = 1; i <= n * n; ++i)
        target_idx[i] = MAX_N - 3 - (n * n - i);

    bfs_dist(sx, sy);

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (isdigit(grid1[i][j]))
                mf.add_edge(mf.s, idx(0, i, j), grid1[i][j] - '0');
            if (isdigit(grid2[i][j]))
                mf.add_edge(target_idx[idx(0, i, j)], mf.t, grid2[i][j] - '0');
            mf.add_edge(idx(0, i, j), target_idx[idx(0, i, j)], INF);
        }
    }

    const int dx[4] = {1, 0, 0, -1};
    const int dy[4] = {0, 1, -1, 0};

    for (int step = 1; step <= t; ++step) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
                for (int k = 0; k < 4; ++k) {
                    int ni = i + dx[k], nj = j + dy[k];
                    if (ni >= 1 && ni <= n && nj >= 1 && nj <= n &&
                        grid1[ni][nj] != 'Y' && grid1[ni][nj] != 'Z' &&
                        dist_grid[i][j] >= step && dist_grid[ni][nj] >= step) {
                        mf.add_edge(idx(step - 1, ni, nj), idx(step, i, j), INF);
                    }
                }
                mf.add_edge(idx(step, i, j), target_idx[idx(0, i, j)], INF);
            }
        }
    }

    cout << mf.max_flow() << '\n';
    return 0;
}
